import{_ as s,o as n,c as a}from"./chunks/framework.D1Ss-Xl7.js";const y=JSON.parse(`{"title":"Page 3 - web | Tag","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"slug":"web/page/3","tag":"web","title":"Page 3 - web | Tag","prev":"/tags/web/page/2/","next":"/tags/web/page/4/","posts":[{"title":"代理Sentry的请求","url":"/posts/2021-12-30-sentry-proxy/","date":"2021-12-30 22:21","tags":["web"],"html":"<p><a href=\\"https://sentry.io/\\" target=\\"_blank\\" rel=\\"noreferrer\\">Sentry</a>是一款非常不错的网页监控工具，可以帮忙收集网页端的报错方便分析用户使用过程中遇到的问题。但是因为有收集用户隐私的风险，有些广告屏蔽软件会屏蔽 Sentry 的请求，所以我们需要使用反向代理的方式，让 Sentry 把请求发到我们自己的后端，我们再转发到 Sentry 服务器上。</p>\\n<h2 id=\\"sentry-端配置\\" tabindex=\\"-1\\">Sentry 端配置 <a class=\\"header-anchor\\" href=\\"#sentry-端配置\\" aria-label=\\"Permalink to &quot;Sentry 端配置&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>添加 <code>tunnel</code> 选项，Sentry 就会把请求发到这个路径下，然后我们后台再处理转发。</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">Sentry.</span><span style=\\"color:#6F42C1\\">init</span><span style=\\"color:#24292E\\">({</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  dsn: </span><span style=\\"color:#032F62\\">'https://examplePublicKey@o0.ingest.sentry.io/0'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  tunnel: </span><span style=\\"color:#032F62\\">'/sentry'</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">});</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br></div></div><h2 id=\\"后台转发请求\\" tabindex=\\"-1\\">后台转发请求 <a class=\\"header-anchor\\" href=\\"#后台转发请求\\" aria-label=\\"Permalink to &quot;后台转发请求&quot;\\">&ZeroWidthSpace;</a></h2>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">app.</span><span style=\\"color:#6F42C1\\">set</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'trust proxy'</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">true</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">app.</span><span style=\\"color:#6F42C1\\">use</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#6F42C1\\">compression</span><span style=\\"color:#24292E\\">());</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">app.</span><span style=\\"color:#6F42C1\\">use</span><span style=\\"color:#24292E\\">(express.</span><span style=\\"color:#6F42C1\\">text</span><span style=\\"color:#24292E\\">());</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">app.</span><span style=\\"color:#6F42C1\\">use</span><span style=\\"color:#24292E\\">(express.</span><span style=\\"color:#6F42C1\\">json</span><span style=\\"color:#24292E\\">());</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">// 注意这三行代码一定要放在前面才能正常处理请求</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">app.</span><span style=\\"color:#6F42C1\\">post</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">/</span><span style=\\"color:#D73A49\\">^</span><span style=\\"color:#22863A;font-weight:bold\\">\\\\/</span><span style=\\"color:#032F62\\">sentry/</span><span style=\\"color:#24292E\\">, (</span><span style=\\"color:#E36209\\">req</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#E36209\\">res</span><span style=\\"color:#24292E\\">) </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> envelope</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> req.body;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> piece</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> envelope.</span><span style=\\"color:#6F42C1\\">split</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'</span><span style=\\"color:#005CC5\\">\\\\n</span><span style=\\"color:#032F62\\">'</span><span style=\\"color:#24292E\\">)[</span><span style=\\"color:#005CC5\\">0</span><span style=\\"color:#24292E\\">];</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> header</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#005CC5\\"> JSON</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#6F42C1\\">parse</span><span style=\\"color:#24292E\\">(piece);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (header.dsn) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    const</span><span style=\\"color:#005CC5\\"> dsn</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> URL</span><span style=\\"color:#24292E\\">(header.dsn);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    const</span><span style=\\"color:#005CC5\\"> projectId</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> dsn.pathname.</span><span style=\\"color:#6F42C1\\">substr</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">1</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    const</span><span style=\\"color:#005CC5\\"> options</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      hostname: dsn.hostname,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      port: </span><span style=\\"color:#005CC5\\">443</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      path: </span><span style=\\"color:#032F62\\">\`/api/\${</span><span style=\\"color:#24292E\\">projectId</span><span style=\\"color:#032F62\\">}/envelope/\`</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      method: </span><span style=\\"color:#032F62\\">'POST'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      headers: {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">        'Content-Type'</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#032F62\\">'application/x-sentry-envelope'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">        'X-Forwarded-For'</span><span style=\\"color:#24292E\\">: req.ip</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    };</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    const</span><span style=\\"color:#005CC5\\"> request</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> https.</span><span style=\\"color:#6F42C1\\">request</span><span style=\\"color:#24292E\\">(options);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    request.</span><span style=\\"color:#6F42C1\\">write</span><span style=\\"color:#24292E\\">(envelope);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    request.</span><span style=\\"color:#6F42C1\\">end</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  res.</span><span style=\\"color:#6F42C1\\">json</span><span style=\\"color:#24292E\\">({});</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">});</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br><span class=\\"line-number\\">17</span><br><span class=\\"line-number\\">18</span><br><span class=\\"line-number\\">19</span><br><span class=\\"line-number\\">20</span><br><span class=\\"line-number\\">21</span><br><span class=\\"line-number\\">22</span><br><span class=\\"line-number\\">23</span><br><span class=\\"line-number\\">24</span><br><span class=\\"line-number\\">25</span><br><span class=\\"line-number\\">26</span><br><span class=\\"line-number\\">27</span><br><span class=\\"line-number\\">28</span><br><span class=\\"line-number\\">29</span><br><span class=\\"line-number\\">30</span><br></div></div><p>后台 Web 服务器是使用经典的 express，转发的时候记得开启<code>trust proxy</code>，因为我们的服务器基本会放在 Load balancing 后面，为了获取到真实的客户 IP 地址，我们需要层层转发保证收集到的信息是真实 IP 地址，而不是我们后端 IP 地址。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>Sentry 的反向代理本身并不是很复杂，但是网络上并没有相关的 JS 代码实现和处理 IP 转发问题，所以希望我的代码例子能帮助大家快速的解决这个问题。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://docs.sentry.io/platforms/javascript/troubleshooting/#dealing-with-ad-blockers\\" target=\\"_blank\\" rel=\\"noreferrer\\">Dealing with Ad-Blockers</a></p>\\n"},{"title":"使用Service Worker的 Web Push 功能","url":"/posts/2021-04-25-service-worker-push/","date":"2021-04-25 12:27","tags":["web"],"html":"<p>现代的 Android 应用和 iOS 应用都有相应的推送系统，可以给用户推送消息。即使用户没有打开这个应用，也同样可以收到消息。当然，网页既然要向手机应用靠拢的话，那推送功能也是必不可少。\\n今天我们就来介绍一下，网页如何实现类似的推送功能。</p>\\n<h2 id=\\"基于-service-worker-的推送功能\\" tabindex=\\"-1\\">基于 Service Worker 的推送功能 <a class=\\"header-anchor\\" href=\\"#基于-service-worker-的推送功能\\" aria-label=\\"Permalink to &quot;基于 Service Worker 的推送功能&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>Service Worker 提供了两种推送服务，一种是基于 Firebase Cloud Messaging 的推送功能，一种是基于 VAPID 的推送功能。第一种已经过时了，所以本文只介绍第二种。</p>\\n<h3 id=\\"create-a-public-private-key-pair\\" tabindex=\\"-1\\">Create a public/private key pair <a class=\\"header-anchor\\" href=\\"#create-a-public-private-key-pair\\" aria-label=\\"Permalink to &quot;Create a public/private key pair&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>首先，我们需要创建公钥和私钥，类似与 HTTPS 的 RSA 加密。客户端使用公钥订阅推送，服务端使用私钥来发送通知。创建既可以在浏览器进行，也可以使用 Node 创建。当然，推荐在后端生成更安全。</p>\\n<p>前端生成代码参考链接：<a href=\\"https://github.com/acgotaku/sw-push/blob/master/src/utils/util.ts\\" target=\\"_blank\\" rel=\\"noreferrer\\">util.ts</a></p>\\n<p>后端使用<a href=\\"https://github.com/web-push-libs/web-push\\" target=\\"_blank\\" rel=\\"noreferrer\\">web-push</a>可以更方便的生成公钥和私钥。代码如下：</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#6F42C1\\"> generateVAPIDKeys</span><span style=\\"color:#24292E\\">() {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> vapidKeys</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> webpush.</span><span style=\\"color:#6F42C1\\">generateVAPIDKeys</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    publicKey: vapidKeys.publicKey,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    privateKey: vapidKeys.privateKey</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  };</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br></div></div><h3 id=\\"subscribing-with-the-public-key\\" tabindex=\\"-1\\">Subscribing with the public key <a class=\\"header-anchor\\" href=\\"#subscribing-with-the-public-key\\" aria-label=\\"Permalink to &quot;Subscribing with the public key&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>接下来我们需要订阅推送：</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">navigator.serviceWorker.ready</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  .</span><span style=\\"color:#6F42C1\\">then</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">registration</span><span style=\\"color:#D73A49\\"> =></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#24292E\\"> registration.pushManager.</span><span style=\\"color:#6F42C1\\">getSubscription</span><span style=\\"color:#24292E\\">().</span><span style=\\"color:#6F42C1\\">then</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">subscription</span><span style=\\"color:#D73A49\\"> =></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">      if</span><span style=\\"color:#24292E\\"> (subscription </span><span style=\\"color:#D73A49\\">===</span><span style=\\"color:#005CC5\\"> null</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        return</span><span style=\\"color:#24292E\\"> registration.pushManager.</span><span style=\\"color:#6F42C1\\">subscribe</span><span style=\\"color:#24292E\\">({</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          userVisibleOnly: </span><span style=\\"color:#005CC5\\">true</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          applicationServerKey: </span><span style=\\"color:#005CC5\\">this</span><span style=\\"color:#24292E\\">.vapidPublicKey</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        });</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      } </span><span style=\\"color:#D73A49\\">else</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        return</span><span style=\\"color:#24292E\\"> subscription;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    });</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  })</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  .</span><span style=\\"color:#6F42C1\\">then</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">subscription</span><span style=\\"color:#D73A49\\"> =></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    this</span><span style=\\"color:#24292E\\">.subJSON </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> subscription.</span><span style=\\"color:#6F42C1\\">toJSON</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  });</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br></div></div><p>我们使用公钥进行订阅，并且把订阅之后的内容打印出来，方便服务器使用。实际工程中需要发送给服务器进行保存。使用 Chrome 浏览器订阅的信息是这样的：</p>\\n<div class=\\"language-json line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">json</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">{</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">  \\"endpoint\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#032F62\\">\\"https://fcm.googleapis.com/fcm/send/d3cMmjx0Eg8:APA91bF1i7wgLJRw-VgOh3Evn6RG1xqdOR6Y0CeTUm1xiD36BCHXaDoceVfilDYiifWdI_rWdU8IdJjqSxaCVscRp5zl9lon8u4mf9mha0fmSVKJzUOx5r5Jba2yiNmCFRxxKcTJm51S\\"</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">  \\"expirationTime\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#005CC5\\">null</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">  \\"keys\\"</span><span style=\\"color:#24292E\\">: {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"p256dh\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#032F62\\">\\"BDtGmJB0Bkyum0WJw8NiiCn4U9ckX8UjhzXPUad2HM0yID0ced8zUHKr-Yhf6p2Z7IS0G07dGG7Tnl5jlwQVog4\\"</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"auth\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#032F62\\">\\"25JGSYqTKvj_nAeodHBHSQ\\"</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br></div></div><p>我们可以看到推送的网址是 Chrome 提供的服务，Firefox 浏览器下订阅的信息是这样的：</p>\\n<div class=\\"language-json line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">json</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">{</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">  \\"endpoint\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#032F62\\">\\"https://updates.push.services.mozilla.com/wpush/v2/gAAAAABghCrItYXGJw0eCyp0Ae1lTxMXkb6Fxhg8tRck2cMoY4bZjvkV2j5t95FfrPftdieUgeaNthjmb0_XyoIVqWIy7cpy9lMjczHb5TYpC7sKnOw4IekwrtQbmBo6Vn54TZaUSrBIb40PEy2KXF5QlyOj2QxlTz6d6NPB6mMvJxuYNSg-5xs\\"</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">  \\"keys\\"</span><span style=\\"color:#24292E\\">: {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"auth\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#032F62\\">\\"MCeQnXlaz4A-CBuALNPbcQ\\"</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"p256dh\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#032F62\\">\\"BL4am0lzx005spT_UBbMagfWb93Cfgh8XtkCtP7y697dODFnO0wCVVI783BsiHePRTl-mrpoHolJ0gKTYR1T4SQ\\"</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br></div></div><p>从 <code>endpoint</code> 我们可以看出推送服务本身是浏览器提供的，如果无法访问这个网址，自然就无法使用推送服务。</p>\\n<h3 id=\\"server-push\\" tabindex=\\"-1\\">Server push <a class=\\"header-anchor\\" href=\\"#server-push\\" aria-label=\\"Permalink to &quot;Server push&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>接下来，我们让服务端发送一个消息试试：</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> webpush</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> require</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'web-push'</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> vapidPublicKey</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#032F62\\"> 'public key'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> vapidPrivateKey</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#032F62\\"> 'private key'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">// PushSubscriptionJSON Info</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> pushSubscription</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  endpoint: </span><span style=\\"color:#032F62\\">''</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  expirationTime: </span><span style=\\"color:#005CC5\\">null</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  keys: {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    p256dh: </span><span style=\\"color:#032F62\\">''</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    auth: </span><span style=\\"color:#032F62\\">''</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">};</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> payload</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#032F62\\"> 'hello world!'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> options</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  vapidDetails: {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    subject: </span><span style=\\"color:#032F62\\">'mailto:example@web-push-node.org'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    publicKey: vapidPublicKey,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    privateKey: vapidPrivateKey</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  },</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  TTL: </span><span style=\\"color:#005CC5\\">60</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">};</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">webpush</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  .</span><span style=\\"color:#6F42C1\\">sendNotification</span><span style=\\"color:#24292E\\">(pushSubscription, payload, options)</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  .</span><span style=\\"color:#6F42C1\\">then</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#E36209\\">result</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    console.</span><span style=\\"color:#6F42C1\\">log</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'success!'</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    console.</span><span style=\\"color:#6F42C1\\">log</span><span style=\\"color:#24292E\\">(result);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  })</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  .</span><span style=\\"color:#6F42C1\\">catch</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#E36209\\">err</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    console.</span><span style=\\"color:#6F42C1\\">log</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'fail!'</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    console.</span><span style=\\"color:#6F42C1\\">error</span><span style=\\"color:#24292E\\">(err);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  });</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br><span class=\\"line-number\\">17</span><br><span class=\\"line-number\\">18</span><br><span class=\\"line-number\\">19</span><br><span class=\\"line-number\\">20</span><br><span class=\\"line-number\\">21</span><br><span class=\\"line-number\\">22</span><br><span class=\\"line-number\\">23</span><br><span class=\\"line-number\\">24</span><br><span class=\\"line-number\\">25</span><br><span class=\\"line-number\\">26</span><br><span class=\\"line-number\\">27</span><br><span class=\\"line-number\\">28</span><br><span class=\\"line-number\\">29</span><br><span class=\\"line-number\\">30</span><br><span class=\\"line-number\\">31</span><br><span class=\\"line-number\\">32</span><br><span class=\\"line-number\\">33</span><br><span class=\\"line-number\\">34</span><br><span class=\\"line-number\\">35</span><br><span class=\\"line-number\\">36</span><br></div></div><p>在上述代码中填入相应的认证信息，就可以使用了。浏览器的推送功能并不需要把相应的网站打开，只要浏览器是打开的就可以收到推送。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>浏览器的推送功能非常方便，但是首先需要用户授权通知权限才能使用，其次是浏览器提供的推送服务，可能在中国无法正常使用。所以现在这个功能还没有大规模的应用。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://developers.google.com/web/ilt/pwa/introduction-to-push-notifications\\" target=\\"_blank\\" rel=\\"noreferrer\\">Introduction to Push Notifications</a></p>\\n<p><a href=\\"https://developers.google.com/web/fundamentals/codelabs/push-notifications\\" target=\\"_blank\\" rel=\\"noreferrer\\">Adding Push Notifications to a Web App</a></p>\\n<p><a href=\\"https://github.com/acgotaku/sw-push\\" target=\\"_blank\\" rel=\\"noreferrer\\">Service Worker Push Notifications Demo</a></p>\\n"},{"title":"前端开发中的加载性能优化","url":"/posts/2020-12-20-loading-performance/","date":"2020-12-20 10:48","tags":["web","performance"],"html":"<p>不同于需要安装的安卓 App 或者 iOS App，前端 App 所有的资源文件都要通过网络进行下载，所以加载速度越快对用户的体验来说就越好。因为我们也需要在加载的时候进行优化，减少不必要的资源请求。</p>\\n<h2 id=\\"文本内容的优化\\" tabindex=\\"-1\\">文本内容的优化 <a class=\\"header-anchor\\" href=\\"#文本内容的优化\\" aria-label=\\"Permalink to &quot;文本内容的优化&quot;\\">&ZeroWidthSpace;</a></h2>\\n<h3 id=\\"压缩代码\\" tabindex=\\"-1\\">压缩代码 <a class=\\"header-anchor\\" href=\\"#压缩代码\\" aria-label=\\"Permalink to &quot;压缩代码&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>HTML，JS，CSS 都有相应的工具可以进行代码压缩，可以使用 webpack 工具方便的进行代码压缩。JS 使用工具<a href=\\"https://github.com/terser/terser\\" target=\\"_blank\\" rel=\\"noreferrer\\">terser</a>，CSS 使用<a href=\\"https://github.com/cssnano/cssnano\\" target=\\"_blank\\" rel=\\"noreferrer\\">CSS Nano</a>, HTML 使用<a href=\\"https://github.com/kangax/html-minifier\\" target=\\"_blank\\" rel=\\"noreferrer\\">HTMLMinifier</a>进行代码压缩。</p>\\n<h3 id=\\"使用-gzip-进行压缩\\" tabindex=\\"-1\\">使用 GZIP 进行压缩 <a class=\\"header-anchor\\" href=\\"#使用-gzip-进行压缩\\" aria-label=\\"Permalink to &quot;使用 GZIP 进行压缩&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>现代化浏览器都支持 GZIP 进行压缩，并且服务器端 NGINX 也可以很方便的配置使用 GZIP 压缩请求的资源文件。</p>\\n<h3 id=\\"减少第三方-js-的引用\\" tabindex=\\"-1\\">减少第三方 JS 的引用 <a class=\\"header-anchor\\" href=\\"#减少第三方-js-的引用\\" aria-label=\\"Permalink to &quot;减少第三方 JS 的引用&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>在 2010 年左右，人们都爱使用 jQuery 框架进行开发，因为 jQuery 抹平了浏览器之间的差异性，大大提高了开发效率。但随着浏览器吸收了 jQuery 的各种优点，例如可以使用<code>document.querySelector</code>很方便的像 jQuery 一样选择元素。现在的前端开发已经不那么需要 jQuery 了，你可以访问<a href=\\"http://youmightnotneedjquery.com/\\" target=\\"_blank\\" rel=\\"noreferrer\\">You might not need jQuery</a>来查找替代的方法。</p>\\n<h3 id=\\"webpack-相关的优化\\" tabindex=\\"-1\\">webpack 相关的优化 <a class=\\"header-anchor\\" href=\\"#webpack-相关的优化\\" aria-label=\\"Permalink to &quot;webpack 相关的优化&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>可以使用 webpack 的<a href=\\"https://webpack.js.org/plugins/split-chunks-plugin/\\" target=\\"_blank\\" rel=\\"noreferrer\\">SplitChunksPlugin</a>， 分割 JS 文件，只打包首次载入需要的 JS 文件来减少网络请求。\\n我们也可以使用<a href=\\"https://webpack.js.org/guides/tree-shaking/\\" target=\\"_blank\\" rel=\\"noreferrer\\">Tree Shaking</a>来引入需要的 JS 库，避免不使用的代码被打包进来。</p>\\n<h2 id=\\"图像内容的优化\\" tabindex=\\"-1\\">图像内容的优化 <a class=\\"header-anchor\\" href=\\"#图像内容的优化\\" aria-label=\\"Permalink to &quot;图像内容的优化&quot;\\">&ZeroWidthSpace;</a></h2>\\n<h3 id=\\"移除不使用的图像\\" tabindex=\\"-1\\">移除不使用的图像 <a class=\\"header-anchor\\" href=\\"#移除不使用的图像\\" aria-label=\\"Permalink to &quot;移除不使用的图像&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>由于网站项目的更新，很多时候有一些不被使用的图像资源被打包进输出目录。这样会导致无谓的资源加载，需要及时发现和删除。</p>\\n<h3 id=\\"选择合适的图像格式\\" tabindex=\\"-1\\">选择合适的图像格式 <a class=\\"header-anchor\\" href=\\"#选择合适的图像格式\\" aria-label=\\"Permalink to &quot;选择合适的图像格式&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>众所周知，png 图像可以展示透明效果，但是 jpg 图像做不到。但是因为 png 比 jpg 多了一个 alpha 通道，所以占用的空间也大，如果不需要透明效果展示，相同的图像效果，jpg 会占用更小的空间。</p>\\n<h3 id=\\"移除图像的-metadata\\" tabindex=\\"-1\\">移除图像的 Metadata <a class=\\"header-anchor\\" href=\\"#移除图像的-metadata\\" aria-label=\\"Permalink to &quot;移除图像的 Metadata&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>图像的 Metadata 对于 web 资源来说并没有什么意义，所以移除 Metadata 可以减少图像占用空间。</p>\\n<h3 id=\\"调整图像尺寸\\" tabindex=\\"-1\\">调整图像尺寸 <a class=\\"header-anchor\\" href=\\"#调整图像尺寸\\" aria-label=\\"Permalink to &quot;调整图像尺寸&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>如果显示的尺寸和实际尺寸差距过大，也会造成不必要的资源浪费。</p>\\n<h3 id=\\"调整图像质量\\" tabindex=\\"-1\\">调整图像质量 <a class=\\"header-anchor\\" href=\\"#调整图像质量\\" aria-label=\\"Permalink to &quot;调整图像质量&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>在很多情况下，对图像质量没有过高的要求，可以损失质量来换取更小的空间。</p>\\n<h3 id=\\"压缩图像\\" tabindex=\\"-1\\">压缩图像 <a class=\\"header-anchor\\" href=\\"#压缩图像\\" aria-label=\\"Permalink to &quot;压缩图像&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>现在有很多算法可以有损或者无损的压缩图像，在发布之前，可以使用压缩工具减少图像的使用空间。</p>\\n<h2 id=\\"http-请求优化\\" tabindex=\\"-1\\">HTTP 请求优化 <a class=\\"header-anchor\\" href=\\"#http-请求优化\\" aria-label=\\"Permalink to &quot;HTTP 请求优化&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>可以使用 HTTP2 协议来提高网站的载入速度，HTTP2 允许多路复用，多个请求可以使用单一的 HTTP 连接来处理，大大提高了载入速度。\\n这里有一个<a href=\\"https://http2.akamai.com/demo\\" target=\\"_blank\\" rel=\\"noreferrer\\">demo</a> 大家可以使用浏览器打开，感受一下。</p>\\n<h2 id=\\"http-cache\\" tabindex=\\"-1\\">HTTP Cache <a class=\\"header-anchor\\" href=\\"#http-cache\\" aria-label=\\"Permalink to &quot;HTTP Cache&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>可以通过缓存技术来提高网站的载入速度，当用户再次访问网站的时候可以直接使用缓存而不必再次请求资源文件。我们甚至可以使用<a href=\\"https://developers.google.com/web/fundamentals/primers/service-workers\\" target=\\"_blank\\" rel=\\"noreferrer\\">Service Workers</a>缓存整个网站，保证可以离线使用。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>载入优化需要从各个方面入手，查找分析前端 App 的资源文件，并从网络请求和缓存下手才能达到最优的效果。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://developers.google.com/web/fundamentals/performance/get-started\\" target=\\"_blank\\" rel=\\"noreferrer\\">Loading Performance</a></p>\\n"}]},"relativePath":"tags/web/page/3/index.md","filePath":"tags/[slug].md"}`),e={name:"tags/web/page/3/index.md"};function p(l,r,o,t,c,i){return n(),a("div")}const u=s(e,[["render",p]]);export{y as __pageData,u as default};
